"""Embedded offline/fallback repository files for dankharaharsh/vulnerable-code."""

VULNERABLE_CODE_FILES = {
    'app.py': '"""\nSecureHub VAPT Training Lab — Core Application Server\nIntentionally Vulnerable Web Application for Authorized Cybersecurity Training and Tracegate Platform Evaluation.\n\nDISCLAIMER & SCOPE:\nThis software is intended exclusively for authorized local cybersecurity education,\npenetration testing validation, and automated AI Fix benchmark evaluation.\nDO NOT DEPLOY THIS APPLICATION ON PUBLIC OR UNTRUSTED NETWORKS.\nBinds strictly to 127.0.0.1.\n"""\n\nimport os\nimport sqlite3\nimport functools\nfrom datetime import datetime\nfrom flask import (\n    Flask, render_template, request, redirect, url_for,\n    session, flash, send_file, abort, g\n)\n\nBASE_DIR = os.path.dirname(os.path.abspath(__file__))\nDATABASE_PATH = os.path.join(BASE_DIR, "securehub.db")\nUPLOAD_FOLDER = os.path.join(BASE_DIR, "uploads")\nLAB_DATA_FOLDER = os.path.join(BASE_DIR, "lab_data")\n\n# Ensure required runtime directories exist\nos.makedirs(UPLOAD_FOLDER, exist_ok=True)\nos.makedirs(LAB_DATA_FOLDER, exist_ok=True)\n\napp = Flask(__name__)\n# Secret key for local session signing\napp.secret_key = "securehub-training-lab-local-session-secret-key"\napp.config["UPLOAD_FOLDER"] = UPLOAD_FOLDER\napp.config["MAX_CONTENT_LENGTH"] = 16 * 1024 * 1024  # 16 MB max upload\n\n\n# -------------------------------------------------------------------------\n# Database Helpers\n# -------------------------------------------------------------------------\n\ndef get_db():\n    """Provides a SQLite connection with row dictionary access."""\n    if "db" not in g:\n        g.db = sqlite3.connect(DATABASE_PATH)\n        g.db.row_factory = sqlite3.Row\n    return g.db\n\n\n@app.teardown_appcontext\ndef close_db(exception=None):\n    """Closes database connection at the end of the request."""\n    db = g.pop("db", None)\n    if db is not None:\n        db.close()\n\n\ndef get_current_user():\n    """Retrieves the active user record based on the session identifier."""\n    user_id = session.get("user_id")\n    if not user_id:\n        return None\n    db = get_db()\n    return db.execute("SELECT * FROM users WHERE id = ?", (user_id,)).fetchone()\n\n\n# -------------------------------------------------------------------------\n# Authentication & Authorization Decorator\n# -------------------------------------------------------------------------\n\ndef login_required(f):\n    """\n    Session verification decorator.\n    \n    VULN-005 (CWE-288): Two-Factor Authentication (2FA) Implementation Bypass\n    Flaw: This decorator only checks whether \'user_id\' exists in session.\n    It fails to verify whether two-factor authentication (\'2fa_verified\')\n    was actually completed by users with \'two_factor_enabled\' = 1.\n    As a result, a user can navigate directly to any protected endpoint\n    without completing the second authentication factor.\n    """\n    @functools.wraps(f)\n    def decorated_function(*args, **kwargs):\n        if "user_id" not in session:\n            flash("Please sign in to access this workspace resource.", "warning")\n            return redirect(url_for("login"))\n        \n        # VULNERABLE LOGIC: Missing enforcement of 2FA completion state!\n        # An AI fix should verify:\n        # if session.get(\'2fa_required\') and not session.get(\'2fa_verified\'):\n        #     return redirect(url_for(\'two_factor_view\'))\n\n        return f(*args, **kwargs)\n    return decorated_function\n\n\n# -------------------------------------------------------------------------\n# Authentication Routes\n# -------------------------------------------------------------------------\n\n@app.route("/login", methods=["GET", "POST"])\ndef login():\n    """\n    Handles user authentication.\n    \n    Contains:\n    - VULN-001 (CWE-524): Insecure Credential Caching & Autocomplete configuration.\n    - VULN-002 (CWE-204): Distinguishable responses revealing valid vs invalid accounts.\n    - VULN-004 (CWE-287): SQL Injection in authentication query construction.\n    """\n    if request.method == "POST":\n        username = request.form.get("username", "").strip()\n        password = request.form.get("password", "")\n        remember_me = request.form.get("remember_me")\n\n        db = get_db()\n\n        # -----------------------------------------------------------------\n        # VULN-004 (CWE-287): Authentication Bypass via SQL Injection\n        # Unsafe string concatenation allows malicious input (e.g. admin\' --)\n        # to manipulate query structure and bypass password verification.\n        # AI Fix: Use parameterized query:\n        # cursor.execute("SELECT * FROM users WHERE username = ? AND password = ?", (username, password))\n        # -----------------------------------------------------------------\n        raw_auth_query = f"SELECT * FROM users WHERE username = \'{username}\' AND password = \'{password}\'"\n        \n        try:\n            cursor = db.cursor()\n            cursor.execute(raw_auth_query)\n            user = cursor.fetchone()\n        except sqlite3.OperationalError:\n            # Fallback if arbitrary syntax breaks query\n            user = None\n\n        if user:\n            # Set active session credentials\n            session["user_id"] = user["id"]\n            session["username"] = user["username"]\n            session["role"] = user["role"]\n\n            # Handle 2FA routing\n            if user["two_factor_enabled"]:\n                session["2fa_required"] = True\n                session["2fa_verified"] = False\n                flash("Two-Factor Authentication is required for your account. Please enter your verification token.", "info")\n                return redirect(url_for("two_factor_view"))\n            else:\n                session["2fa_required"] = False\n                session["2fa_verified"] = True\n                flash(f"Welcome back, {user[\'display_name\'] or user[\'username\']}!", "success")\n                return redirect(url_for("dashboard"))\n\n        # -----------------------------------------------------------------\n        # VULN-002 (CWE-204): Account & Username Enumeration\n        # Distinguishable error messages allow attackers to verify whether\n        # a given username exists in the system directory.\n        # AI Fix: Return a uniform response: "Invalid username or password."\n        # -----------------------------------------------------------------\n        account_lookup = db.execute("SELECT * FROM users WHERE username = ?", (username,)).fetchone()\n        if not account_lookup:\n            flash("Account with this username does not exist.", "error")\n        else:\n            flash("Incorrect password for user.", "error")\n\n        return render_template("login.html")\n\n    # VULN-001 (CWE-524): Note that the login page lacks Cache-Control: no-store\n    return render_template("login.html")\n\n\n@app.route("/logout")\ndef logout():\n    """Clears the session and redirects to sign in."""\n    session.clear()\n    flash("You have been signed out successfully.", "info")\n    return redirect(url_for("login"))\n\n\n# -------------------------------------------------------------------------\n# Two-Factor Authentication Route\n# -------------------------------------------------------------------------\n\n@app.route("/2fa", methods=["GET", "POST"])\n@login_required\ndef two_factor_view():\n    """\n    Two-Factor Authentication management and verification challenge.\n    \n    Part of VULN-005 (CWE-288): 2FA Implementation Bypass.\n    """\n    user = get_current_user()\n    db = get_db()\n\n    if request.method == "POST":\n        action = request.form.get("action")\n\n        if action == "verify_code":\n            entered_code = request.form.get("code", "").strip()\n            # Standard training code accepted: 123456\n            if entered_code == "123456" or entered_code == user["two_factor_secret"]:\n                session["2fa_verified"] = True\n                session["2fa_required"] = False\n                flash("Two-factor code verified successfully. Authentication complete.", "success")\n                return redirect(url_for("dashboard"))\n            else:\n                flash("Invalid two-factor code. Please try again.", "error")\n\n        elif action == "toggle_2fa":\n            new_state = 0 if user["two_factor_enabled"] else 1\n            secret = "TEST2FA" + user["username"].upper() if new_state else None\n            db.execute(\n                "UPDATE users SET two_factor_enabled = ?, two_factor_secret = ? WHERE id = ?",\n                (new_state, secret, user["id"])\n            )\n            db.commit()\n            flash(f"Two-factor authentication {\'enabled\' if new_state else \'disabled\'}.", "success")\n            return redirect(url_for("two_factor_view"))\n\n    return render_template("2fa.html", user=user, current_user=user, active_page="2fa")\n\n\n# -------------------------------------------------------------------------\n# Dashboard & Core SaaS Views\n# -------------------------------------------------------------------------\n\n@app.route("/")\n@app.route("/dashboard")\n@login_required\ndef dashboard():\n    """Main SaaS operational dashboard."""\n    user = get_current_user()\n    db = get_db()\n\n    total_users = db.execute("SELECT COUNT(*) as count FROM users").fetchone()["count"]\n    total_files = db.execute("SELECT COUNT(*) as count FROM files").fetchone()["count"]\n    total_comments = db.execute("SELECT COUNT(*) as count FROM comments").fetchone()["count"]\n\n    recent_comments = db.execute("""\n        SELECT c.*, u.username, u.display_name \n        FROM comments c \n        JOIN users u ON c.user_id = u.id \n        ORDER BY c.id DESC LIMIT 5\n    """).fetchall()\n\n    stats = {\n        "total_users": total_users,\n        "total_files": total_files,\n        "total_comments": total_comments,\n    }\n\n    return render_template(\n        "dashboard.html",\n        user=user,\n        current_user=user,\n        stats=stats,\n        recent_comments=recent_comments,\n        active_page="dashboard"\n    )\n\n\n# -------------------------------------------------------------------------\n# Profile & IDOR Route\n# -------------------------------------------------------------------------\n\n@app.route("/profile")\n@login_required\ndef profile_view():\n    """Displays active user\'s personal profile."""\n    user = get_current_user()\n    return render_template("profile.html", user=user, current_user=user, active_page="profile")\n\n\n@app.route("/profile/edit", methods=["GET", "POST"])\n@login_required\ndef profile_edit():\n    """\n    Profile update form and submission handler.\n    \n    VULN-008 (CWE-639): Insecure Direct Object References (IDOR) / BOLA\n    The endpoint accepts a user_id from client form data and executes an\n    update against that record without checking if user_id matches session[\'user_id\']\n    or if the requesting user has administrative privileges.\n    AI Fix: Derive identity from session[\'user_id\'] or perform server authorization check:\n    target_user_id = session[\'user_id\']\n    """\n    current_user = get_current_user()\n    db = get_db()\n\n    if request.method == "POST":\n        # VULNERABLE LOGIC: Trusting client-supplied user_id instead of session identity\n        target_user_id = request.form.get("user_id")\n        display_name = request.form.get("display_name", "").strip()\n        phone = request.form.get("phone", "").strip()\n        address = request.form.get("address", "").strip()\n        bio = request.form.get("bio", "").strip()\n\n        # Update profile for target_user_id directly\n        db.execute("""\n            UPDATE users\n            SET display_name = ?, phone = ?, address = ?, bio = ?\n            WHERE id = ?\n        """, (display_name, phone, address, bio, target_user_id))\n        db.commit()\n\n        flash(f"Profile record #{target_user_id} updated successfully.", "success")\n        return redirect(url_for("profile_view"))\n\n    return render_template("profile_edit.html", user=current_user, current_user=current_user, active_page="profile")\n\n\n# -------------------------------------------------------------------------\n# User Directory Views\n# -------------------------------------------------------------------------\n\n@app.route("/users")\n@login_required\ndef users_list():\n    """Directory of all corporate users."""\n    user = get_current_user()\n    db = get_db()\n    users = db.execute("SELECT id, username, email, role, display_name, two_factor_enabled FROM users ORDER BY id ASC").fetchall()\n    return render_template("users.html", users=users, current_user=user, active_page="users")\n\n\n@app.route("/user/<int:user_id>")\n@login_required\ndef user_detail(user_id):\n    """View a single user\'s public profile card."""\n    current_user = get_current_user()\n    db = get_db()\n    target_user = db.execute("SELECT * FROM users WHERE id = ?", (user_id,)).fetchone()\n    if not target_user:\n        flash("Target user record not found.", "error")\n        return redirect(url_for("users_list"))\n    return render_template("user_detail.html", target_user=target_user, current_user=current_user, active_page="users")\n\n\n# -------------------------------------------------------------------------\n# Operations Comments (Log)\n# -------------------------------------------------------------------------\n\n@app.route("/comments", methods=["GET", "POST"])\n@login_required\ndef comments_view():\n    """\n    Team operations comments log.\n    Safely renders user entries (Jinja2 auto-escaping) so this feature\n    does not create a second XSS vulnerability.\n    """\n    current_user = get_current_user()\n    db = get_db()\n\n    if request.method == "POST":\n        comment_text = request.form.get("comment_text", "").strip()\n        if comment_text:\n            db.execute(\n                "INSERT INTO comments (user_id, comment_text) VALUES (?, ?)",\n                (current_user["id"], comment_text)\n            )\n            db.commit()\n            flash("Operations log entry posted successfully.", "success")\n            return redirect(url_for("comments_view"))\n\n    comments = db.execute("""\n        SELECT c.*, u.username, u.display_name \n        FROM comments c \n        JOIN users u ON c.user_id = u.id \n        ORDER BY c.id DESC\n    """).fetchall()\n\n    return render_template("comments.html", comments=comments, current_user=current_user, active_page="comments")\n\n\n# -------------------------------------------------------------------------\n# File Management & Vulnerable Upload / Download Handlers\n# -------------------------------------------------------------------------\n\n@app.route("/upload", methods=["GET", "POST"])\n@login_required\ndef upload_view():\n    """\n    File upload endpoint.\n    \n    VULN-007 (CWE-434): Arbitrary File Upload via Unrestricted Extension Validation\n    The server relies on an inadequate extension blocklist (only rejecting .exe and .bat)\n    rather than a strict allowlist. It accepts unsafe file extensions such as .php, .svg,\n    .html, .sh, or script documents, and preserves original extensions on the filesystem.\n    AI Fix: Enforce a strict allowlist of extensions, validate MIME types and magic bytes,\n    and generate safe pseudo-random filenames.\n    """\n    current_user = get_current_user()\n    db = get_db()\n\n    if request.method == "POST":\n        if "file" not in request.files:\n            flash("No file part provided in request.", "error")\n            return redirect(url_for("upload_view"))\n\n        file = request.files["file"]\n        if file.filename == "":\n            flash("No file selected for upload.", "error")\n            return redirect(url_for("upload_view"))\n\n        original_filename = file.filename\n        _, ext = os.path.splitext(original_filename)\n        ext = ext.lower()\n\n        # -----------------------------------------------------------------\n        # VULNERABLE LOGIC: Weak extension blocklist instead of strict allowlist\n        # -----------------------------------------------------------------\n        DISALLOWED_EXTENSIONS = {".exe", ".bat", ".cmd", ".dll"}\n        if ext in DISALLOWED_EXTENSIONS:\n            flash(f"Security Alert: Upload of executable format \'{ext}\' is prohibited.", "danger")\n            return redirect(url_for("upload_view"))\n\n        # Save file into upload folder with user-provided filename\n        stored_filename = f"{int(datetime.now().timestamp())}_{original_filename}"\n        save_path = os.path.join(app.config["UPLOAD_FOLDER"], stored_filename)\n        file.save(save_path)\n\n        file_size = os.path.getsize(save_path)\n        mime_type = file.content_type or "application/octet-stream"\n\n        # Record file metadata in database\n        db.execute("""\n            INSERT INTO files (user_id, original_filename, stored_filename, mime_type, size)\n            VALUES (?, ?, ?, ?, ?)\n        """, (current_user["id"], original_filename, stored_filename, mime_type, file_size))\n        db.commit()\n\n        flash(f"Asset \'{original_filename}\' successfully uploaded and indexed.", "success")\n        return redirect(url_for("uploads_gallery"))\n\n    return render_template("upload.html", current_user=current_user, active_page="upload")\n\n\n@app.route("/uploads")\n@login_required\ndef uploads_gallery():\n    """\n    Storage pool gallery and SVG renderer.\n    \n    VULN-003 (CWE-79): Stored Cross-Site Scripting (XSS) via SVG Upload\n    Uploaded SVG files are read from storage and provided directly to the\n    template, which renders the SVG content unsafely with the |safe filter\n    without script sanitization or Content Security Policy.\n    AI Fix: Sanitize SVG XML content or serve it strictly as a non-executable attachment.\n    """\n    current_user = get_current_user()\n    db = get_db()\n\n    files = db.execute("""\n        SELECT f.*, u.username as uploader_name \n        FROM files f \n        LEFT JOIN users u ON f.user_id = u.id \n        ORDER BY f.id DESC\n    """).fetchall()\n\n    files_list = []\n    svg_files = []\n\n    for f in files:\n        f_dict = dict(f)\n        is_svg = f["original_filename"].lower().endswith(".svg") or "svg" in f["mime_type"].lower()\n        f_dict["is_svg"] = is_svg\n        files_list.append(f_dict)\n\n        if is_svg:\n            file_path = os.path.join(app.config["UPLOAD_FOLDER"], f["stored_filename"])\n            if os.path.exists(file_path):\n                try:\n                    with open(file_path, "r", encoding="utf-8", errors="ignore") as svg_file:\n                        f_dict["svg_content"] = svg_file.read()\n                        svg_files.append(f_dict)\n                except Exception:\n                    pass\n\n    return render_template(\n        "uploads.html",\n        files=files_list,\n        svg_files=svg_files,\n        current_user=current_user,\n        active_page="uploads"\n    )\n\n\n@app.route("/files/download")\n@login_required\ndef download_file():\n    """\n    File download retrieval endpoint.\n    \n    VULN-006: Path Traversal / Destination Storage Directory Escape\n    The endpoint constructs the filesystem path directly using os.path.join(UPLOAD_FOLDER, filename)\n    without canonicalization or verifying that the target remains inside UPLOAD_FOLDER.\n    Attackers can pass traversal sequences (e.g. ?file=../../lab_data/training_note.txt)\n    to read safe training artifacts outside the upload repository.\n    AI Fix:\n    base_dir = os.path.realpath(app.config[\'UPLOAD_FOLDER\'])\n    target_path = os.path.realpath(os.path.join(base_dir, requested_file))\n    if not target_path.startswith(base_dir + os.path.sep):\n        abort(403, "Directory traversal prohibited")\n    """\n    requested_file = request.args.get("file", "")\n    if not requested_file:\n        flash("No target file specified for download.", "error")\n        return redirect(url_for("uploads_gallery"))\n\n    # -----------------------------------------------------------------\n    # VULNERABLE LOGIC: Unsafe path construction without canonicalization\n    # -----------------------------------------------------------------\n    target_path = os.path.join(app.config["UPLOAD_FOLDER"], requested_file)\n\n    # Support flexible relative traversal depth for lab training files\n    if not os.path.exists(target_path):\n        alt_path = os.path.join(BASE_DIR, requested_file)\n        if os.path.exists(alt_path):\n            target_path = alt_path\n        elif "training_note.txt" in requested_file and os.path.exists(os.path.join(LAB_DATA_FOLDER, "training_note.txt")):\n            target_path = os.path.join(LAB_DATA_FOLDER, "training_note.txt")\n\n    if os.path.exists(target_path):\n        return send_file(target_path, as_attachment=True)\n    else:\n        flash(f"Requested asset \'{requested_file}\' could not be located in storage pool.", "error")\n        return redirect(url_for("uploads_gallery"))\n\n\n# -------------------------------------------------------------------------\n# Application Entry Point\n# -------------------------------------------------------------------------\n\nif __name__ == "__main__":\n    print("=" * 70)\n    print(" SecureHub VAPT Training Lab — Authorized Local Environment")\n    print(" Target: http://127.0.0.1:5000")\n    print(" WARNING: Intentionally vulnerable for local training & Tracegate testing.")\n    print("=" * 70)\n    app.run(host="127.0.0.1", port=5000, debug=False)\n',
    'templates/login.html': '<!DOCTYPE html>\n<html lang="en">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>Sign In — SecureHub VAPT Training Lab</title>\n    <link rel="stylesheet" href="{{ url_for(\'static\', filename=\'css/style.css\') }}">\n</head>\n<body class="auth-wrapper">\n    <div class="auth-card">\n        <div class="auth-header">\n            <div class="brand-logo">S</div>\n            <h1>SecureHub Portal</h1>\n            <p>Authorized Cybersecurity Training Lab</p>\n        </div>\n\n        {% with messages = get_flashed_messages(with_categories=true) %}\n            {% if messages %}\n                <div class="flash-messages">\n                    {% for category, message in messages %}\n                        <div class="alert alert-{{ category if category != \'error\' else \'danger\' }}">\n                            <span>{{ message }}</span>\n                        </div>\n                    {% endfor %}\n                </div>\n            {% endif %}\n        {% endwith %}\n\n        <!-- \n            VULN-001 (CWE-524): Insecure Credential Caching & Form Autocomplete\n            The form and sensitive credential fields explicitly enable autocomplete ("on"),\n            allowing sensitive authentication secrets to be cached by client user-agents.\n        -->\n        <form method="POST" action="{{ url_for(\'login\') }}" autocomplete="on" class="auth-form">\n            <div class="form-group">\n                <label class="form-label" for="username">Username or Corporate ID</label>\n                <input type="text" id="username" name="username" class="form-control" placeholder="e.g. alice" autocomplete="on" required autofocus>\n            </div>\n\n            <div class="form-group">\n                <div style="display: flex; justify-content: space-between; align-items: center;">\n                    <label class="form-label" for="password">Password</label>\n                </div>\n                <input type="password" id="password" name="password" class="form-control" placeholder="••••••••" autocomplete="on" required>\n            </div>\n\n            <div class="form-group">\n                <div class="form-check">\n                    <input type="checkbox" id="remember_me" name="remember_me" class="form-check-input" checked>\n                    <label for="remember_me" class="form-check-label">Remember credentials on this machine</label>\n                </div>\n            </div>\n\n            <div class="form-group" style="margin-top: 24px;">\n                <button type="submit" class="btn btn-primary btn-block">Sign In</button>\n            </div>\n        </form>\n\n        <div style="margin-top: 24px; padding-top: 20px; border-top: 1px solid var(--border-color); font-size: 12px; color: var(--text-muted);">\n            <div style="font-weight: 600; margin-bottom: 6px; color: var(--text-main);">Test Lab Accounts (Local Only):</div>\n            <ul style="padding-left: 18px; line-height: 1.6;">\n                <li><code>alice</code> / <code>alice123</code> (2FA Protected)</li>\n                <li><code>bob</code> / <code>bob123</code> (Standard User)</li>\n                <li><code>charlie</code> / <code>charlie123</code> (Standard User)</li>\n                <li><code>admin</code> / <code>admin123</code> (System Administrator)</li>\n            </ul>\n        </div>\n    </div>\n</body>\n</html>\n',
    'templates/uploads.html': '{% extends "base.html" %}\n\n{% block title %}Asset Storage Pool{% endblock %}\n{% block header_title %}Storage Pool & File Browser{% endblock %}\n\n{% block header_actions %}\n<a href="{{ url_for(\'upload_view\') }}" class="btn btn-primary btn-sm">+ Upload New File</a>\n{% endblock %}\n\n{% block content %}\n<div class="card">\n    <div class="card-header">\n        <h2>Managed Files & Documents</h2>\n        <span style="font-size: 13px; color: var(--text-muted);">{{ files|length }} Files Recorded</span>\n    </div>\n    <div class="card-body" style="padding: 0;">\n        {% if files %}\n        <div class="table-responsive">\n            <table class="table">\n                <thead>\n                    <tr>\n                        <th>Asset ID</th>\n                        <th>Original Name</th>\n                        <th>Stored Reference</th>\n                        <th>Content Type</th>\n                        <th>Size</th>\n                        <th>Uploaded By</th>\n                        <th>Date</th>\n                        <th>Actions</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    {% for f in files %}\n                    <tr>\n                        <td style="font-weight: 600; color: var(--text-muted);">#{{ f.id }}</td>\n                        <td style="font-weight: 600;">\n                            {% if f.is_svg %}\n                                <span style="margin-right: 4px;">🖼️</span>\n                            {% else %}\n                                <span style="margin-right: 4px;">📄</span>\n                            {% endif %}\n                            {{ f.original_filename }}\n                        </td>\n                        <td><code>{{ f.stored_filename }}</code></td>\n                        <td><span class="badge badge-user">{{ f.mime_type }}</span></td>\n                        <td>{{ (f.size / 1024)|round(1) }} KB</td>\n                        <td>{{ f.uploader_name or \'System\' }}</td>\n                        <td style="font-size: 12px; color: var(--text-muted);">{{ f.created_at }}</td>\n                        <td>\n                            <!-- Path traversal vulnerable download link (VULN-006) -->\n                            <a href="{{ url_for(\'download_file\', file=f.stored_filename) }}" class="btn btn-secondary btn-sm" download>\n                                ⬇ Download\n                            </a>\n                        </td>\n                    </tr>\n                    {% endfor %}\n                </tbody>\n            </table>\n        </div>\n        {% else %}\n        <div style="padding: 40px; text-align: center; color: var(--text-muted);">\n            <div style="font-size: 40px; margin-bottom: 12px;">📁</div>\n            <p>No files uploaded yet. Upload a document or SVG vector image to get started.</p>\n        </div>\n        {% endif %}\n    </div>\n</div>\n\n<!-- SVG Vector Render Preview Gallery -->\n{% if svg_files %}\n<div class="card" style="margin-top: 32px;">\n    <div class="card-header">\n        <h2>SVG Vector Graphics Preview Gallery</h2>\n        <span class="badge badge-info">Direct Vector Rendering</span>\n    </div>\n    <div class="card-body">\n        <p style="font-size: 14px; color: var(--text-muted); margin-bottom: 20px;">\n            The portal renders uploaded SVG graphics directly for operations team visualization.\n        </p>\n\n        <div style="display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 24px;">\n            {% for svg in svg_files %}\n            <div style="border: 1px solid var(--border-color); border-radius: var(--radius); padding: 16px; background: #ffffff;">\n                <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px;">\n                    <span style="font-weight: 600; font-size: 14px;">{{ svg.original_filename }}</span>\n                    <a href="{{ url_for(\'download_file\', file=svg.stored_filename) }}" class="btn btn-secondary btn-sm">Download</a>\n                </div>\n\n                <!-- \n                    VULN-003 (CWE-79): Stored Cross-Site Scripting (XSS) via SVG Upload\n                    The application renders untrusted SVG content directly and unsafely\n                    into the DOM using Jinja2\'s |safe filter without sanitization,\n                    causing active embedded <script> tags or event handlers to execute.\n                -->\n                <div class="svg-preview-container">\n                    {{ svg.svg_content | safe }}\n                </div>\n                \n                <div style="font-size: 11px; color: var(--text-muted); margin-top: 8px;">\n                    Uploaded on {{ svg.created_at }} &bull; Stored as: <code>{{ svg.stored_filename }}</code>\n                </div>\n            </div>\n            {% endfor %}\n        </div>\n    </div>\n</div>\n{% endif %}\n{% endblock %}\n',
    'templates/2fa.html': '{% extends "base.html" %}\n\n{% block title %}Two-Factor Authentication{% endblock %}\n{% block header_title %}Security & Two-Factor Authentication{% endblock %}\n\n{% block content %}\n<div style="display: grid; grid-template-columns: 1fr 1fr; gap: 28px; max-width: 960px;">\n    <!-- 2FA Code Verification / Challenge -->\n    <div class="card">\n        <div class="card-header">\n            <h2>Two-Factor Code Verification</h2>\n            {% if user.two_factor_enabled %}\n                <span class="badge badge-success">Active</span>\n            {% else %}\n                <span class="badge badge-warning">Optional</span>\n            {% endif %}\n        </div>\n        <div class="card-body">\n            <p style="font-size: 14px; color: var(--text-muted); margin-bottom: 20px;">\n                Enter the 6-digit one-time verification token generated by your mobile authenticator application.\n            </p>\n\n            <form method="POST" action="{{ url_for(\'two_factor_view\') }}">\n                <input type="hidden" name="action" value="verify_code">\n\n                <div class="form-group">\n                    <label class="form-label" for="code">Authenticator Code</label>\n                    <input type="text" id="code" name="code" class="form-control" placeholder="123456" maxlength="8" style="font-size: 20px; letter-spacing: 0.25em; text-align: center;" required>\n                    <span class="form-hint">Standard training code: <code>123456</code></span>\n                </div>\n\n                <div style="margin-top: 24px;">\n                    <button type="submit" class="btn btn-primary btn-block">Verify Token</button>\n                </div>\n            </form>\n\n            <div style="margin-top: 20px; font-size: 12px; color: var(--text-muted); line-height: 1.5;">\n                <strong>Flow Note:</strong> Users with 2FA enabled are routed here after login. However, if backend authorization checks fail to enforce completed 2FA state, protected resources may remain accessible directly.\n            </div>\n        </div>\n    </div>\n\n    <!-- 2FA Configuration / Management -->\n    <div class="card">\n        <div class="card-header">\n            <h2>Authentication Settings</h2>\n        </div>\n        <div class="card-body">\n            <h4 style="font-size: 15px; margin-bottom: 8px;">Multi-Factor Status</h4>\n            <p style="font-size: 14px; color: var(--text-muted); margin-bottom: 16px;">\n                {% if user.two_factor_enabled %}\n                    Two-factor authentication is currently <strong>enabled</strong> for this corporate account.\n                {% else %}\n                    Two-factor authentication is currently <strong>disabled</strong> for this corporate account.\n                {% endif %}\n            </p>\n\n            <div style="background: #f8fafc; padding: 14px; border-radius: var(--radius); border: 1px solid var(--border-color); margin-bottom: 20px;">\n                <div style="font-size: 12px; font-weight: 600; text-transform: uppercase; color: var(--text-muted); margin-bottom: 4px;">Assigned 2FA Secret Key</div>\n                <code style="font-size: 14px; font-weight: 700; color: #1e293b;">{{ user.two_factor_secret or \'NOT-GENERATED\' }}</code>\n            </div>\n\n            <form method="POST" action="{{ url_for(\'two_factor_view\') }}">\n                <input type="hidden" name="action" value="toggle_2fa">\n                {% if user.two_factor_enabled %}\n                    <button type="submit" class="btn btn-danger btn-block">Disable Two-Factor Authentication</button>\n                {% else %}\n                    <button type="submit" class="btn btn-primary btn-block">Enable Two-Factor Authentication</button>\n                {% endif %}\n            </form>\n        </div>\n    </div>\n</div>\n{% endblock %}\n',
    'templates/profile.html': '{% extends "base.html" %}\n\n{% block title %}My Profile{% endblock %}\n{% block header_title %}User Account Profile{% endblock %}\n\n{% block header_actions %}\n<a href="{{ url_for(\'profile_edit\') }}" class="btn btn-primary btn-sm">Edit Profile</a>\n{% endblock %}\n\n{% block content %}\n<div class="card" style="max-width: 800px;">\n    <div class="card-header">\n        <h2>Profile Overview</h2>\n        <span class="badge badge-{{ \'admin\' if user.role == \'admin\' else \'user\' }}">{{ user.role }}</span>\n    </div>\n    <div class="card-body">\n        <div style="display: flex; align-items: center; gap: 20px; margin-bottom: 28px; padding-bottom: 20px; border-bottom: 1px solid var(--border-color);">\n            <div class="user-avatar" style="width: 64px; height: 64px; font-size: 24px; background: #2563eb;">\n                {{ user.username[0].upper() }}\n            </div>\n            <div>\n                <h2 style="font-size: 20px; font-weight: 700;">{{ user.display_name or user.username }}</h2>\n                <div style="color: var(--text-muted); font-size: 14px;">@{{ user.username }} &bull; {{ user.email }}</div>\n            </div>\n        </div>\n\n        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 20px;">\n            <div>\n                <label class="form-label" style="color: var(--text-muted); font-size: 12px; text-transform: uppercase;">User ID</label>\n                <div style="font-weight: 600; font-size: 15px;">#{{ user.id }}</div>\n            </div>\n\n            <div>\n                <label class="form-label" style="color: var(--text-muted); font-size: 12px; text-transform: uppercase;">Corporate Email</label>\n                <div style="font-weight: 600; font-size: 15px;">{{ user.email }}</div>\n            </div>\n\n            <div>\n                <label class="form-label" style="color: var(--text-muted); font-size: 12px; text-transform: uppercase;">Contact Phone</label>\n                <div style="font-weight: 500; font-size: 15px;">{{ user.phone or \'Not configured\' }}</div>\n            </div>\n\n            <div>\n                <label class="form-label" style="color: var(--text-muted); font-size: 12px; text-transform: uppercase;">Two-Factor Authentication</label>\n                <div>\n                    {% if user.two_factor_enabled %}\n                        <span class="badge badge-success">Enabled</span>\n                    {% else %}\n                        <span class="badge badge-warning">Disabled</span>\n                    {% endif %}\n                </div>\n            </div>\n\n            <div style="grid-column: 1 / -1;">\n                <label class="form-label" style="color: var(--text-muted); font-size: 12px; text-transform: uppercase;">Office / Mailing Address</label>\n                <div style="font-weight: 500; font-size: 15px;">{{ user.address or \'Not specified\' }}</div>\n            </div>\n\n            <div style="grid-column: 1 / -1;">\n                <label class="form-label" style="color: var(--text-muted); font-size: 12px; text-transform: uppercase;">Bio / Department Role</label>\n                <div style="font-weight: 500; font-size: 15px; color: #334155; line-height: 1.6;">\n                    {{ user.bio or \'No biographical information added.\' }}\n                </div>\n            </div>\n        </div>\n\n        <div style="margin-top: 32px; padding-top: 20px; border-top: 1px solid var(--border-color); display: flex; gap: 12px;">\n            <a href="{{ url_for(\'profile_edit\') }}" class="btn btn-primary">Modify Information</a>\n            <a href="{{ url_for(\'two_factor_view\') }}" class="btn btn-secondary">Security & 2FA</a>\n        </div>\n    </div>\n</div>\n{% endblock %}\n',
    'templates/upload.html': '{% extends "base.html" %}\n\n{% block title %}Upload Asset{% endblock %}\n{% block header_title %}File Asset Upload{% endblock %}\n\n{% block header_actions %}\n<a href="{{ url_for(\'uploads_gallery\') }}" class="btn btn-secondary btn-sm">View Storage Pool &rarr;</a>\n{% endblock %}\n\n{% block content %}\n<div style="display: grid; grid-template-columns: 1.2fr 1fr; gap: 28px; max-width: 1050px;">\n    <!-- Upload Form Card -->\n    <div class="card">\n        <div class="card-header">\n            <h2>Upload Digital Document / Media</h2>\n        </div>\n        <div class="card-body">\n            <!--\n                VULN-007 (CWE-434): Arbitrary File Upload via Unrestricted Extension Validation\n                The backend upload handler relies on a flawed extension blocklist rather than\n                a strict allowlist, permitting files with executable, script, or active formats.\n            -->\n            <form method="POST" action="{{ url_for(\'upload_view\') }}" enctype="multipart/form-data">\n                <div class="form-group">\n                    <label class="form-label" for="file">Select File</label>\n                    <div class="upload-dropzone" onclick="document.getElementById(\'file\').click();">\n                        <div style="font-size: 36px; margin-bottom: 8px;">📂</div>\n                        <div style="font-weight: 600; font-size: 15px; color: var(--text-main);">Click to browse files</div>\n                        <div style="font-size: 12px; color: var(--text-muted); margin-top: 4px;">Supports SVGs, images, documents, reports</div>\n                        <div id="file-selected-name" style="margin-top: 10px; font-weight: 600; color: var(--primary); font-size: 13px;">No file chosen</div>\n                    </div>\n                    <input type="file" id="file" name="file" style="display: none;" required>\n                </div>\n\n                <div class="form-group">\n                    <label class="form-label" for="description">Asset Description (Optional)</label>\n                    <input type="text" id="description" name="description" class="form-control" placeholder="e.g. Q3 Security Vector Graphic / Audit Memo">\n                </div>\n\n                <div style="margin-top: 24px;">\n                    <button type="submit" class="btn btn-primary btn-block">Upload to SecureHub</button>\n                </div>\n            </form>\n        </div>\n    </div>\n\n    <!-- Upload Guidelines & File Policy -->\n    <div class="card">\n        <div class="card-header">\n            <h2>Storage Policy & Guidelines</h2>\n        </div>\n        <div class="card-body" style="font-size: 14px; color: #334155; line-height: 1.6;">\n            <h4 style="font-size: 14px; font-weight: 700; margin-bottom: 8px; color: var(--text-main);">Storage Pool Guidelines</h4>\n            <p style="margin-bottom: 12px;">\n                Assets uploaded here are indexed into the central storage directory under <code>uploads/</code> and assigned unique tracking identifiers.\n            </p>\n\n            <div style="background: #f8fafc; border: 1px solid var(--border-color); border-radius: var(--radius); padding: 14px; margin-bottom: 16px;">\n                <div style="font-size: 12px; font-weight: 600; text-transform: uppercase; color: var(--text-muted); margin-bottom: 6px;">Permitted Formats</div>\n                <div style="font-size: 13px; color: #475569;">\n                    Images, SVG graphics, text logs, analysis reports.\n                </div>\n            </div>\n\n            <div style="font-size: 12px; color: var(--text-muted);">\n                <strong>VAPT Training Scope:</strong> Files uploaded to this lab environment are stored locally in the isolated lab repository for security evaluation.\n            </div>\n        </div>\n    </div>\n</div>\n{% endblock %}\n',
    'templates/dashboard.html': '{% extends "base.html" %}\n\n{% block title %}Dashboard{% endblock %}\n{% block header_title %}Operations Dashboard{% endblock %}\n\n{% block header_actions %}\n<a href="{{ url_for(\'upload_view\') }}" class="btn btn-primary btn-sm">+ Upload Asset</a>\n{% endblock %}\n\n{% block content %}\n<div class="card" style="background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%); color: white; border: none; margin-bottom: 28px;">\n    <div class="card-body" style="padding: 32px;">\n        <h1 style="font-size: 24px; font-weight: 700; margin-bottom: 8px;">Welcome back, {{ current_user[\'display_name\'] or current_user[\'username\'] }}!</h1>\n        <p style="color: #94a3b8; font-size: 14px; max-width: 600px;">\n            SecureHub Operations Center is running in local training mode. Access security metrics, team logs, managed file repositories, and user authorization controls below.\n        </p>\n    </div>\n</div>\n\n<!-- Key Metrics Grid -->\n<div class="metrics-grid">\n    <div class="metric-card">\n        <div class="metric-header">\n            <span class="metric-title">Active Users</span>\n            <span class="metric-icon">👥</span>\n        </div>\n        <div class="metric-value">{{ stats.total_users }}</div>\n        <div class="metric-caption">Seeded corporate accounts</div>\n    </div>\n\n    <div class="metric-card">\n        <div class="metric-header">\n            <span class="metric-title">Managed Assets</span>\n            <span class="metric-icon">📁</span>\n        </div>\n        <div class="metric-value">{{ stats.total_files }}</div>\n        <div class="metric-caption">Files in local storage</div>\n    </div>\n\n    <div class="metric-card">\n        <div class="metric-header">\n            <span class="metric-title">Operations Log</span>\n            <span class="metric-icon">💬</span>\n        </div>\n        <div class="metric-value">{{ stats.total_comments }}</div>\n        <div class="metric-caption">Recorded log entries</div>\n    </div>\n\n    <div class="metric-card">\n        <div class="metric-header">\n            <span class="metric-title">2FA Protection</span>\n            <span class="metric-icon">🔐</span>\n        </div>\n        <div class="metric-value" style="font-size: 20px; line-height: 32px;">\n            {% if current_user[\'two_factor_enabled\'] %}\n                <span class="badge badge-success">Enforced</span>\n            {% else %}\n                <span class="badge badge-warning">Optional</span>\n            {% endif %}\n        </div>\n        <div class="metric-caption">Multi-factor state</div>\n    </div>\n</div>\n\n<div style="display: grid; grid-template-columns: 2fr 1fr; gap: 24px;">\n    <!-- Recent Activity Log -->\n    <div class="card">\n        <div class="card-header">\n            <h3>Recent Operations Log</h3>\n            <a href="{{ url_for(\'comments_view\') }}" class="btn btn-secondary btn-sm">View All</a>\n        </div>\n        <div class="card-body">\n            {% if recent_comments %}\n                {% for comment in recent_comments %}\n                <div class="comment-item">\n                    <div class="comment-header">\n                        <span class="comment-author">{{ comment.username }}</span>\n                        <span class="comment-time">{{ comment.created_at }}</span>\n                    </div>\n                    <!-- Safely rendered comment body (no XSS) -->\n                    <div class="comment-content">{{ comment.comment_text }}</div>\n                </div>\n                {% endfor %}\n            {% else %}\n                <p style="color: var(--text-muted); font-size: 14px;">No recent comments posted yet.</p>\n            {% endif %}\n        </div>\n    </div>\n\n    <!-- Quick Navigation Actions -->\n    <div class="card">\n        <div class="card-header">\n            <h3>Quick Actions</h3>\n        </div>\n        <div class="card-body" style="display: flex; flex-direction: column; gap: 10px;">\n            <a href="{{ url_for(\'profile_view\') }}" class="btn btn-secondary" style="justify-content: flex-start;">\n                <span>👤</span> My Profile Details\n            </a>\n            <a href="{{ url_for(\'users_list\') }}" class="btn btn-secondary" style="justify-content: flex-start;">\n                <span>👥</span> Team Member Directory\n            </a>\n            <a href="{{ url_for(\'two_factor_view\') }}" class="btn btn-secondary" style="justify-content: flex-start;">\n                <span>🔐</span> Multi-Factor Authentication\n            </a>\n            <a href="{{ url_for(\'upload_view\') }}" class="btn btn-secondary" style="justify-content: flex-start;">\n                <span>📤</span> Upload File Asset\n            </a>\n            <a href="{{ url_for(\'uploads_gallery\') }}" class="btn btn-secondary" style="justify-content: flex-start;">\n                <span>📁</span> Browse Storage Pool\n            </a>\n        </div>\n    </div>\n</div>\n{% endblock %}\n',
    'templates/base.html': '<!DOCTYPE html>\n<html lang="en">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>{% block title %}SecureHub{% endblock %} — VAPT Training Lab</title>\n    <link rel="stylesheet" href="{{ url_for(\'static\', filename=\'css/style.css\') }}">\n</head>\n<body>\n    <div class="lab-banner">\n        <span>🛡️ <strong>SecureHub VAPT Training Lab</strong> — Authorized Local Environment (127.0.0.1)</span>\n    </div>\n\n    <div class="app-container">\n        <!-- Sidebar Navigation -->\n        <aside class="sidebar">\n            <div class="brand-header">\n                <div class="brand-logo">S</div>\n                <div class="brand-title">SecureHub</div>\n                <span class="brand-badge">Lab</span>\n            </div>\n\n            <nav class="nav-menu">\n                <div class="nav-section-title">Core Modules</div>\n                <a href="{{ url_for(\'dashboard\') }}" class="nav-item {% if active_page == \'dashboard\' %}active{% endif %}">\n                    <span class="nav-icon">📊</span>\n                    <span>Dashboard</span>\n                </a>\n                <a href="{{ url_for(\'users_list\') }}" class="nav-item {% if active_page == \'users\' %}active{% endif %}">\n                    <span class="nav-icon">👥</span>\n                    <span>Team Directory</span>\n                </a>\n                <a href="{{ url_for(\'comments_view\') }}" class="nav-item {% if active_page == \'comments\' %}active{% endif %}">\n                    <span class="nav-icon">💬</span>\n                    <span>Operations Log</span>\n                </a>\n\n                <div class="nav-section-title">File Management</div>\n                <a href="{{ url_for(\'upload_view\') }}" class="nav-item {% if active_page == \'upload\' %}active{% endif %}">\n                    <span class="nav-icon">📤</span>\n                    <span>Upload Asset</span>\n                </a>\n                <a href="{{ url_for(\'uploads_gallery\') }}" class="nav-item {% if active_page == \'uploads\' %}active{% endif %}">\n                    <span class="nav-icon">📁</span>\n                    <span>Asset Storage</span>\n                </a>\n\n                <div class="nav-section-title">Account & Security</div>\n                <a href="{{ url_for(\'profile_view\') }}" class="nav-item {% if active_page == \'profile\' %}active{% endif %}">\n                    <span class="nav-icon">👤</span>\n                    <span>My Profile</span>\n                </a>\n                <a href="{{ url_for(\'two_factor_view\') }}" class="nav-item {% if active_page == \'2fa\' %}active{% endif %}">\n                    <span class="nav-icon">🔐</span>\n                    <span>2FA Settings</span>\n                </a>\n                <a href="{{ url_for(\'logout\') }}" class="nav-item">\n                    <span class="nav-icon">🚪</span>\n                    <span>Sign Out</span>\n                </a>\n            </nav>\n\n            {% if current_user %}\n            <div class="sidebar-user">\n                <div class="user-avatar">{{ current_user[\'username\'][0].upper() }}</div>\n                <div class="user-info">\n                    <div class="user-name">{{ current_user[\'display_name\'] or current_user[\'username\'] }}</div>\n                    <div class="user-role">{{ current_user[\'role\'] }}</div>\n                </div>\n            </div>\n            {% endif %}\n        </aside>\n\n        <!-- Main Content -->\n        <main class="main-wrapper">\n            <header class="top-navbar">\n                <div class="page-headline">{% block header_title %}Workspace Overview{% endblock %}</div>\n                <div class="top-actions">\n                    {% block header_actions %}{% endblock %}\n                </div>\n            </header>\n\n            <div class="content-container">\n                <!-- Flash Messages -->\n                {% with messages = get_flashed_messages(with_categories=true) %}\n                    {% if messages %}\n                        <div class="flash-messages">\n                            {% for category, message in messages %}\n                                <div class="alert alert-{{ category if category != \'error\' else \'danger\' }}">\n                                    <span>{{ message }}</span>\n                                </div>\n                            {% endfor %}\n                        </div>\n                    {% endif %}\n                {% endwith %}\n\n                {% block content %}{% endblock %}\n            </div>\n        </main>\n    </div>\n\n    <script src="{{ url_for(\'static\', filename=\'js/app.js\') }}"></script>\n    {% block scripts %}{% endblock %}\n</body>\n</html>\n',
    'requirements.txt': 'Flask>=3.0.0\nrequests>=2.31.0\n',
    'README.md': '# SecureHub VAPT Training Lab\n\n```text\n=============================================================================\nTHIS APPLICATION IS INTENTIONALLY VULNERABLE.\nUSE ONLY FOR AUTHORIZED LOCAL SECURITY TRAINING.\nDO NOT DEPLOY THIS APPLICATION TO THE PUBLIC INTERNET.\n=============================================================================\n```\n\n**SecureHub VAPT Training Lab** is a server-rendered web application built for local cybersecurity training, penetration testing exercises, and benchmarking the **Tracegate Platform** (Screenshot Analysis, VAPT Checklist Generation, Finding Verification, PoC Collection, DOCX Reporting, and AI Fix Before/After Code Remediation).\n\n---\n\n## 1. Safety & Operational Scope\n\n- **Binding Address:** Strictly `127.0.0.1:5000` (Localhost only).\n- **Data Safety:** All accounts, passwords, emails, and phone numbers are completely synthetic dummy training values.\n- **Path Traversal Scope:** Restricted to safe, local lab training artifacts (`lab_data/training_note.txt`). No system-level credentials or sensitive OS paths are exposed or targeted.\n- **File Upload Scope:** Demonstrates improper extension filtering and active vector rendering without hosting live executable payloads.\n\n---\n\n## 2. Technology Stack\n\n- **Backend:** Python 3 (Flask 3.x)\n- **Database:** SQLite 3 (`securehub.db`)\n- **Frontend:** Server-rendered HTML5, responsive SaaS CSS (`static/css/style.css`), vanilla JavaScript (`static/js/app.js`)\n- **File Storage:** Local filesystem (`uploads/`)\n\n---\n\n## 3. Project Structure\n\n```text\nsecurehub-vapt-lab/\n├── app.py                      # Flask backend, routing, authentication, and vulnerable handlers\n├── reset_lab.py                # Standalone CLI reset script (rebuilds DB, seeds users & files)\n├── test_lab.py                 # Automated verification test suite for all 8 vulnerabilities\n├── requirements.txt            # Python dependencies\n├── README.md                   # Complete lab documentation and vulnerability mapping\n├── lab_data/\n│   └── training_note.txt       # Safe target file for Path Traversal testing\n├── uploads/                    # Local asset storage directory\n│   ├── sample_report.txt       # Seed sample document\n│   └── sample_diagram.svg      # Seed vector diagram\n├── static/\n│   ├── css/\n│   │   └── style.css           # Modern SaaS stylesheet (navy/slate theme, cards, tables, badges)\n│   └── js/\n│       └── app.js              # Client UI helper scripts\n└── templates/\n    ├── base.html               # Base layout with navbar, alerts, footer, and branding\n    ├── login.html              # VULN-001 (autocomplete), VULN-002 (enumeration), VULN-004 (SQLi)\n    ├── dashboard.html          # Main operational dashboard with metrics & activity logs\n    ├── profile.html            # Profile viewer\n    ├── profile_edit.html       # VULN-008 (IDOR on profile update)\n    ├── users.html              # Team member directory\n    ├── user_detail.html        # Individual user public profile card\n    ├── comments.html           # Operations discussion log (safely escaped)\n    ├── 2fa.html                # VULN-005 (2FA challenge and management)\n    ├── upload.html             # VULN-007 (Arbitrary file upload form)\n    └── uploads.html            # VULN-003 (Stored SVG XSS direct vector rendering)\n```\n\n---\n\n## 4. Setup & Running Instructions\n\n### Prerequisites\n- Python 3.10+\n- pip\n\n### 1. Install Dependencies\n```bash\npip install -r requirements.txt\n```\n\n### 2. Initialize / Reset Lab Environment\nAlways initialize or restore the database and files before running tests:\n```bash\npython reset_lab.py\n```\n\n### 3. Start the Web Application\n```bash\npython app.py\n```\nOpen your browser and navigate to:\n```text\nhttp://127.0.0.1:5000\n```\n\n### 4. Run Automated Vulnerability Verification Suite\nExecute the test suite to verify that all 8 vulnerabilities are active and exploitable:\n```bash\npython test_lab.py\n```\n\n---\n\n## 5. Seed Test Credentials\n\n| Username | Password | Role | 2FA Status | Purpose / Test Target |\n|---|---|---|---|---|\n| `alice` | `alice123` | Standard User | Enabled (`TEST2FAALICE`) | 2FA Implementation Bypass (VULN-005), IDOR Source (VULN-008) |\n| `bob` | `bob123` | Standard User | Disabled | IDOR Target Profile (VULN-008), Path Traversal (VULN-006) |\n| `charlie` | `charlie123` | Standard User | Disabled | SVG XSS Upload (VULN-003), Arbitrary Upload (VULN-007) |\n| `admin` | `admin123` | Administrator | Disabled | SQL Injection Auth Bypass (VULN-004) |\n\n---\n\n## 6. Route Directory\n\n| Route | Methods | Purpose |\n|---|---|---|\n| `/login` | GET, POST | User sign-in interface (VULN-001, VULN-002, VULN-004) |\n| `/logout` | GET | Clears active session and redirects to `/login` |\n| `/dashboard` | GET | Main SaaS operations dashboard and metrics |\n| `/profile` | GET | View current user\'s profile information |\n| `/profile/edit` | GET, POST | Modify profile details (VULN-008 IDOR) |\n| `/users` | GET | Corporate team member directory |\n| `/user/<id>` | GET | Public profile card for specific user ID |\n| `/comments` | GET, POST | Operations discussion board (safely escaped) |\n| `/2fa` | GET, POST | Multi-factor verification and settings (VULN-005) |\n| `/upload` | GET, POST | Upload digital media and documents (VULN-007) |\n| `/uploads` | GET | Storage browser and SVG vector renderer (VULN-003) |\n| `/files/download` | GET | File retrieval endpoint (VULN-006 Path Traversal) |\n\n---\n\n## 7. Security Finding Map & Vulnerability Inventory\n\n### VULN-001: Credential Caching & Form Autocomplete Directive\n- **Identifier:** `VULN-001`\n- **CWE:** CWE-524 (Information Exposure through Caching)\n- **Source File:** `templates/login.html` (lines ~26-44) and `app.py` (`login()`)\n- **Intentional Representation:** Form and sensitive input fields explicitly enable browser autocomplete (`autocomplete="on"`), and authentication routes lack `Cache-Control: no-store` headers.\n- **Proof of Concept:** Inspect page source of `/login`. Observe `<form autocomplete="on">` and `<input type="password" autocomplete="on">`.\n- **Expected AI Fix Target:** Replace with `autocomplete="off"` / `autocomplete="current-password"`, and add `Cache-Control: no-store, no-cache, must-revalidate` response header.\n\n---\n\n### VULN-002: Username & Account Enumeration\n- **Identifier:** `VULN-002`\n- **CWE:** CWE-204 (Observable Response Discrepancy)\n- **Source File:** `app.py` (`login()` lines ~138-150)\n- **Intentional Representation:** Login endpoint issues distinct flash error messages:\n  - Existing user + wrong password: `"Incorrect password for user."`\n  - Non-existent user + wrong password: `"Account with this username does not exist."`\n- **Proof of Concept:**\n  - Submit `bob` with password `wrong` -> Response includes `"Incorrect password for user."`\n  - Submit `ghostuser` with password `wrong` -> Response includes `"Account with this username does not exist."`\n- **Expected AI Fix Target:** Return a uniform error message: `"Invalid username or password."`\n\n---\n\n### VULN-003: Stored Cross-Site Scripting (XSS) via SVG Upload\n- **Identifier:** `VULN-003`\n- **CWE:** CWE-79 (Improper Neutralization of Input During Web Page Generation)\n- **Source File:** `app.py` (`uploads_gallery()`) and `templates/uploads.html` (lines ~80-100)\n- **Intentional Representation:** Uploaded `.svg` files are read from the filesystem and injected raw into the DOM via Jinja\'s `| safe` filter: `{{ svg.svg_content | safe }}` without sanitization or CSP.\n- **Proof of Concept:**\n  1. Upload an SVG file containing:\n     ```xml\n     <svg xmlns="http://www.w3.org/2000/svg"><script>alert(\'TRACEGATE-XSS-VERIFIED\')</script></svg>\n     ```\n  2. Navigate to `/uploads`.\n  3. The JavaScript executes inline when the SVG gallery renders.\n- **Expected AI Fix Target:** Sanitize SVG XML content (stripping `<script>` and event handlers), enforce `Content-Security-Policy: default-src \'self\'`, or serve SVGs strictly as non-inline attachments.\n\n---\n\n### VULN-004: Authentication Bypass via SQL Injection\n- **Identifier:** `VULN-004`\n- **CWE:** CWE-287 (Improper Authentication) / CWE-89 (SQL Injection)\n- **Source File:** `app.py` (`login()` lines ~105-120)\n- **Intentional Representation:** Raw string formatting constructs the authentication query:\n  ```python\n  raw_auth_query = f"SELECT * FROM users WHERE username = \'{username}\' AND password = \'{password}\'"\n  ```\n- **Proof of Concept:**\n  1. Navigate to `/login`.\n  2. In Username enter: `admin\' --`\n  3. In Password enter any arbitrary text.\n  4. Submit form. The database authenticates the session immediately as `admin` without verifying password.\n- **Expected AI Fix Target:** Use parameterized SQL queries:\n  ```python\n  cursor.execute("SELECT * FROM users WHERE username = ? AND password = ?", (username, password))\n  ```\n\n---\n\n### VULN-005: Two-Factor Authentication (2FA) Implementation Bypass\n- **Identifier:** `VULN-005`\n- **CWE:** CWE-288 (Authentication Bypass Using an Alternate Path or Channel)\n- **Source File:** `app.py` (`@login_required` decorator and `login()` route)\n- **Intentional Representation:** Upon password verification for accounts with 2FA enabled (e.g. `alice`), the server populates `session[\'user_id\']` immediately before prompting for the 2FA code at `/2fa`. However, `@login_required` only checks `if \'user_id\' not in session:` and fails to check `session[\'2fa_verified\']`.\n- **Proof of Concept:**\n  1. Sign in as `alice` / `alice123`.\n  2. The application redirects to `/2fa`.\n  3. Instead of entering the 2FA code, directly change browser URL to `/dashboard` or `/profile`.\n  4. Access is granted without completing the second authentication factor.\n- **Expected AI Fix Target:** Maintain a temporary pre-authentication state (`session[\'pre_auth_user_id\']`), and strictly require `session[\'2fa_verified\'] == True` in `@login_required` before granting access to protected routes.\n\n---\n\n### VULN-006: Path Traversal / Destination Storage Directory Escape\n- **Identifier:** `VULN-006`\n- **CWE:** CWE-22 (Improper Limitation of a Pathname to a Restricted Directory)\n- **Source File:** `app.py` (`download_file()` lines ~360-380)\n- **Intentional Representation:** Query parameter `?file=` is joined directly to the upload directory path:\n  ```python\n  target_path = os.path.join(app.config["UPLOAD_FOLDER"], requested_file)\n  ```\n  without verifying canonical containment.\n- **Proof of Concept:**\n  1. Authenticate with any user account.\n  2. Request:\n     ```text\n     /files/download?file=../lab_data/training_note.txt\n     ```\n  3. The server downloads the confidential training document outside the upload repository.\n- **Expected AI Fix Target:** Resolve canonical paths using `os.path.realpath()` and verify target path starts with `os.path.realpath(app.config[\'UPLOAD_FOLDER\']) + os.path.sep`.\n\n---\n\n### VULN-007: Arbitrary File Upload via Unrestricted Extension Validation\n- **Identifier:** `VULN-007`\n- **CWE:** CWE-434 (Unrestricted Upload of File with Dangerous Type)\n- **Source File:** `app.py` (`upload_view()` lines ~275-305)\n- **Intentional Representation:** Server-side upload handler relies on an incomplete blocklist (`.exe`, `.bat`, `.cmd`, `.dll`) rather than a strict allowlist. It accepts `.php`, `.phtml`, `.svg`, `.html`, `.py`, `.sh`, `.config` extensions and retains original extensions in storage.\n- **Proof of Concept:**\n  1. Authenticate and navigate to `/upload`.\n  2. Choose a file named `audit_tool.php` or `config.json`.\n  3. Upload succeeds and file is stored in `uploads/` and indexed in the storage pool.\n- **Expected AI Fix Target:** Enforce strict allowlist of permitted extensions (`.png`, `.jpg`, `.jpeg`, `.gif`, `.pdf`, `.txt`), validate MIME types and file headers, and assign randomized storage filenames.\n\n---\n\n### VULN-008: Insecure Direct Object References (IDOR) on Profile Update\n- **Identifier:** `VULN-008`\n- **CWE:** CWE-639 (Authorization Bypass Through User-Controlled Key)\n- **Source File:** `app.py` (`profile_edit()` lines ~200-220) & `templates/profile_edit.html`\n- **Intentional Representation:** The profile edit form submits a client-controlled hidden `user_id` field. The backend updates the record matching `request.form.get(\'user_id\')` without verifying session identity or role.\n- **Proof of Concept:**\n  1. Sign in as `alice` (`user_id = 1`).\n  2. Navigate to `/profile/edit`.\n  3. Change the hidden field `<input name="user_id" value="2">` (target: Bob Brown).\n  4. Submit form. Bob\'s profile (`display_name`, `phone`, `address`, `bio`) is updated by Alice.\n- **Expected AI Fix Target:** Disregard client-supplied `user_id` and update strictly by `session[\'user_id\']`, or perform server-side ownership authorization before persisting changes.\n\n---\n\n## 8. Tracegate Integration & AI Fix Workflow\n\nThis repository is optimized for Tracegate\'s end-to-end automated and manual penetration testing workflow:\n\n```text\n1. Run vulnerable application locally (python app.py)\n2. Capture screenshots of core modules:\n   - Login (/login)\n   - Dashboard (/dashboard)\n   - Profile (/profile)\n   - Two-Factor Authentication (/2fa)\n   - Asset Upload (/upload)\n   - Storage Pool (/uploads)\n   - Team Directory (/users)\n3. Generate Tracegate VAPT Checklist\n4. Perform authorized test & record PoC evidence\n5. Save Security Finding (VULN-001 through VULN-008)\n6. Trigger AI Fix in Tracegate:\n   - Connect repository\n   - Select vulnerability and affected source file\n   - Analyze vulnerable code block\n   - Review proposed BEFORE / AFTER unified diff\n7. Apply fix via dedicated branch:\n   - Branch: tracegate/fix/VULN-XXX (never overwrite main/master)\n   - Verify source file Git SHA before committing\n8. Run python test_lab.py to confirm vulnerability remediation\n```\n',
}
